<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth;
class AuthController { public function create(){ return view('auth.login'); } public function store(Request $request){ $data=$request->validate(['email'=>['required','email'],'password'=>['required']]); if(!Auth::attempt($data,$request->boolean('remember'))) return back()->withErrors(['email'=>'Email atau kata sandi tidak sesuai.'])->onlyInput('email'); if(!$request->user()->is_active){ Auth::logout(); return back()->withErrors(['email'=>'Akun tidak aktif.']); } $request->session()->regenerate(); return redirect()->intended(route('portal.dashboard')); } public function destroy(Request $request){ Auth::logout(); $request->session()->invalidate(); $request->session()->regenerateToken(); return redirect()->route('login'); } }
